import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url)),tripDataCode=readFileSync(resolve(__dirname,"../../trip-data.js"),"utf-8"),getTripData=new Function(tripDataCode+"\nreturn { tripDestinations };"),{tripDestinations:tripDestinations}=getTripData();globalThis.tripDestinations=tripDestinations;const plannerCode=readFileSync(resolve(__dirname,"../../frontend/js-modules/trip-planner.js"),"utf-8");new Function(plannerCode)();const TripPlanner=globalThis.TripPlanner;describe("TripPlanner Core Logic",()=>{it("should compute haversine distance correctly",()=>{const e=TripPlanner.haversineDistanceKm(28.6139,77.209,28.6139,77.209);expect(e).toBe(0);const t=TripPlanner.haversineDistanceKm(28.6139,77.209,27.1767,78.0081);expect(t).toBeGreaterThan(150),expect(t).toBeLessThan(250)}),it("should choose correct cost tier based on daily budget",()=>{expect(TripPlanner.chooseCostTier(2e3,10)).toBe("budget"),expect(TripPlanner.chooseCostTier(35e3,10)).toBe("mid"),expect(TripPlanner.chooseCostTier(1e5,10)).toBe("luxury")}),it("should generate a valid itinerary",()=>{const e=TripPlanner.generateItinerary({budget:5e4,days:7,travelers:1,categories:["mountains"]});expect(e.destinations.length).toBeGreaterThan(0),expect(e.daysUsed).toBeLessThanOrEqual(7),expect(e.budget.grandTotal).toBeGreaterThan(0)})}),describe("TripPlanner URL Serialization/Deserialization",()=>{it("should serialize inputs to query parameters correctly",()=>{const e=TripPlanner.serializeParams({budget:45e3,days:8,travelers:2,categories:["beaches","adventure"]});expect(e).toContain("budget=45000"),expect(e).toContain("days=8"),expect(e).toContain("travelers=2"),expect(e).toContain("categories=beaches%2Cadventure")}),it("should deserialize query parameters back to inputs object",()=>{const e=TripPlanner.deserializeParams("?budget=55000&days=6&travelers=3&categories=historical,spiritual");expect(e.budget).toBe(55e3),expect(e.days).toBe(6),expect(e.travelers).toBe(3),expect(e.categories).toEqual(["historical","spiritual"])}),it("should handle empty/missing parameters during deserialization",()=>{const e=TripPlanner.deserializeParams("");expect(e.budget).toBeNull(),expect(e.days).toBeNull(),expect(e.travelers).toBe(1),expect(e.categories).toEqual([])})});